def _expected_cortex_training_fields(training: dict) -> dict:
    expected = deepcopy(training)
    if "enable_gradient_checkpointing" in expected:
        expected["activation_checkpointing"] = expected.pop("enable_gradient_checkpointing")
    if expected.get("model_provider") == "prime_rl":
        expected["model_provider"] = "arctic"
    return expected


