@pytest.mark.parametrize("probe_status", [0, 1, 2], ids=["occupied", "idle", "probe-error"])
def test_dss_driver_runtime_idle_check_requires_successful_process_inventory(monkeypatch, tmp_path, probe_status):
    import subprocess

