        ("dss.ray_dss.zones.server", "sampling", "gpu", False),
        ("dss.ray_dss.zones.server", "training", "cpu", False),
        ("dss.ray_dss.zones.server_head", "training", "gpu", False),
        ("unrelated.module", "training", "gpu", False),
