@pytest.mark.parametrize("primary_failure", [False, True])
def test_owned_worker_session_cleanup_new_real_retitled_child_exits_before_worker(primary_failure):
    import textwrap

    source = textwrap.dedent(
        "\n        import signal\n        import subprocess\n        import sys\n        from types import"
        " SimpleNamespace\n        from arctic_platform.correctness.harness import lora as native_lora\n\n       "
        ' children = []\n        child_source = (\n            "import signal, time, setproctitle;"\n           '
        ' "signal.signal(signal.SIGTERM, signal.SIG_IGN);"\n           '
        " \"setproctitle.setproctitle('ray::OwnedWorkerCleanupTest');\"\n            \"print('ready', flush=True);\"\n"
        '            "time.sleep(120)"\n        )\n        worker = SimpleNamespace(signal=signal)\n        primary ='
        ' RuntimeError("worker primary")\n\n        def main():\n            child = subprocess.Popen([sys.executable,'
        ' "-c", child_source], stdout=subprocess.PIPE, text=True)\n            children.append(child)\n           '
        ' assert child.stdout.readline().strip() == "ready"\n            print("OWNED_WORKER_CHILD " + str(child.pid),'
        ' flush=True)\n            if sys.argv[1] == "primary":\n                raise primary\n\n        worker.main'
        " = main\n        try:\n            try:\n                native_lora._owned_worker_session(worker)\n         "
        '   except RuntimeError as error:\n                assert sys.argv[1] == "primary" and error is primary\n     '
        "       assert len(children) == 1 and children[0].wait(timeout=2) == -signal.SIGKILL\n           "
        ' print("OWNED_WORKER_DESCENDANTS_EXITED", flush=True)\n        finally:\n            for child in children:\n'
        "                if child.poll() is None:\n                    child.kill()\n                   "
        " child.wait(timeout=5)\n    "
    )
    completed = subprocess.run(
        [
            "setsid",
            "--wait",
            "env",
            "DSS_CORRECTNESS_GATEWAY_OWNER=" + "b" * 32,
            "SPT_NOENV=1",
            sys.executable,
            "-c",
            source,
            "primary" if primary_failure else "normal",
        ],
        stdin=subprocess.DEVNULL,
        capture_output=True,
        text=True,
        timeout=45,
    )
    print(completed.stdout, end="")
    print(completed.stderr, end="")
    assert completed.returncode == 0
    assert "OWNED_WORKER_DESCENDANTS_EXITED" in completed.stdout


