# Cortex checkpoint export.


_cortex_checkpoint_export_JOB_ID = "0abf38e6-80f6-49cc-820d-883c8c451df4"

_cortex_checkpoint_export_CP_ID = "cp_dc1ee034-d625-4989-8164-092903a8d150"

