@pytest.mark.parametrize(
    "options, expected",
    [
        ({}, "best-effort"),
        ({"determinism": "off"}, "off"),
        ({"preserve_native_topology": True}, "best-effort"),
    ],
)
def test_hosted_checkpoint_calibration_transport_forwards_determinism(monkeypatch, options, expected):
    cfg = load_config(_local_cortex_checkpoint_load_CONFIG)
    backend = CortexConfig(base_url="http://127.0.0.1:8003")
    configs = []
    config = object()

    def build(cfg_arg, backend_arg, **kwargs):
        assert cfg_arg is cfg and backend_arg is backend
        configs.append(kwargs)
        return config

    class Client:
        def __init__(self, config_arg):
            assert config_arg is config
            self.jobs = SimpleNamespace(require=lambda role: "owned-child:training")

        def __enter__(self):
            return self

        def __exit__(self, *args):
            pass

    monkeypatch.setattr(hosted, "training_client_config", build)
    monkeypatch.setattr(hosted, "ArcticClient", Client)
    with hosted.HostedTransport(
        backend, cfg, model_name="/data-fast/control-reviewed-fixture", **options
    ) as transport:
        with transport.job() as job:
            assert job.job_id == "owned-child"
    assert configs == [
        {
            "source_checkpoint_info": None,
            "attn_implementation": None,
            "model_name": "/data-fast/control-reviewed-fixture",
            "determinism": expected,
            "spec": None,
            "published_fixture": None,
            **({"preserve_native_topology": True} if options.get("preserve_native_topology") else {}),
        }
    ]


@pytest.mark.parametrize("native", [False, True])
@pytest.mark.parametrize("asynchronous", [False, True])
@pytest.mark.parametrize("reply", ["inline", "polled", "chunked"])
@pytest.mark.parametrize("stage", [None, _local_cortex_checkpoint_load_STAGE])
def test_local_cortex_checkpoint_load_owned_cp_load_uses_real_delivery_polling_loop_and_owned_shutdown(
    _local_cortex_checkpoint_load_gateway, native, asynchronous, reply, stage
):
    state, create = _local_cortex_checkpoint_load_gateway
    client = create(native=native)
    state.reply = reply
    transport = client.transport
    before = deepcopy(stage)
    with client:
        assert (
            _local_cortex_checkpoint_load_load(client, stage=stage, asynchronous=asynchronous)
            == _local_cortex_checkpoint_load_RESULT
        )
        assert stage == before
        sends = list(state.calls)
        assert sends[0][0] == "POST" and sends[0][1].endswith(f"/{transport.job_id}/load")
        assert sends[0][2]["json"] == {
            "checkpoint_id": _local_cortex_checkpoint_load_CHECKPOINT_ID,
            **({} if stage is None else {"stage_info": stage}),
        }
        assert len(sends) == (1 if reply == "inline" else 2)
        if reply != "inline":
            assert sends[1][0] == "GET"
            assert sends[1][1].endswith(f"/{transport.job_id}/requests/owned-load-request")
    assert [method for method, _, _ in state.calls[-2:]] == ["POST", "GET"]
    assert state.calls[-2][1].endswith(":cancel")
    assert transport.job_id is None and transport._session is None
    assert transport._native_bindings == transport._native_children == {}
    assert transport._local_shutdown_parent is None and transport._local_shutdown_children == {}
    assert len(state.closed) == 1
    session, loop = state.closed[0]
    assert loop is transport._loop and session.closed
    assert all((actual_session is session and actual_loop is loop for actual_session, actual_loop in state.exchanges))


