def test_local_cortex_checkpoint_load_hosted_explicit_stage_resume_uses_real_client_without_source_job_rewrite(
    _local_cortex_checkpoint_load_gateway,
):
    state, _ = _local_cortex_checkpoint_load_gateway
    identity = hosted.LocalCortexCheckpoint(
        _local_cortex_checkpoint_load_CHECKPOINT_ID,
        "saving-parent",
        "/data-fast/tmp/retained",
        "global_step10",
        10,
        stage_info=deepcopy(_local_cortex_checkpoint_load_STAGE),
    )
    with hosted.HostedTransport(
        CortexConfig(base_url="http://127.0.0.1:8003"),
        load_config(_local_cortex_checkpoint_load_CONFIG),
    ) as transport:
        with transport.job(resume_from=identity) as job:
            assert isinstance(job.client, CorrectnessClient)
            state.clients.append(job.client)
            creates = [
                kwargs["json"]
                for method, url, kwargs in state.calls
                if method == "POST" and url.endswith("/cortex-training")
            ]
            assert len(creates) == 1
            assert "source_checkpoint_info" not in creates[0]["sub_job_configs"][0]
            loads = [
                kwargs["json"] for method, url, kwargs in state.calls if method == "POST" and url.endswith("/load")
            ]
            assert loads == [
                {
                    "checkpoint_id": _local_cortex_checkpoint_load_CHECKPOINT_ID,
                    "stage_info": _local_cortex_checkpoint_load_STAGE,
                }
            ]
    assert len(state.closed) == 1 and state.clients[0].transport._session is None


