def test_hosted_local_resume_refuses_a_valid_fast_marker_before_allocating_job(monkeypatch, tmp_path) -> None:
    (tmp_path / "latest").write_text("global_step10\n", encoding="ascii")
    client = _hosted_LocalClient()
