    inputs = {
        f"{attn}.{leaf}.weight": _tensor((2, 4), index + 1)
        for index, leaf in enumerate(("q_proj", "k_proj", "v_proj", "b_proj", "forget_gate.f_a_proj", "g_a_proj"))
    }
