    def forbidden_helper(*args):
        pytest.fail("sampling helper called after rejected full export")

    monkeypatch.setattr(inference_rl_check, "validate_local_inference_export", invalid_export)
    monkeypatch.setattr(inference_rl_check, "_sampling_payload", forbidden_helper)
