@pytest.mark.parametrize(
    "config_path,topology,expected_slots",
    [
        (_inference_sampling_topology_FLASH_CONFIG, (8, 8, 1), 16),
        (_inference_sampling_topology_FLASH_CONFIG, (16, 8, 2), 16),
        (_inference_sampling_topology_ORDINARY_CONFIG, None, 5),
    ],
)
def test_inference_sampling_topology_opt_in_gateway_reuses_training_capacity_only_after_destruction(
    monkeypatch, tmp_path, config_path, topology, expected_slots
):
    ctx = _inference_sampling_topology_context(config_path, topology=topology)
    ctx.workdir = tmp_path
    events = []
    steps = []
    rows = [[-2.0]]
    distribution = {
        "examples": 1,
        "minimum_tokens": 4,
        "median_tokens": 4,
        "maximum_tokens": 4,
    }
    monkeypatch.setattr(inference_rl_check.gsm8k, "load_tokenizer", lambda path: object())
    monkeypatch.setattr(inference_rl_check, "_minimum_context_parallel_row_tokens", lambda *args: 0)
    monkeypatch.setattr(inference_rl_check.gsm8k, "padding_token_id", lambda tokenizer: 0)
    monkeypatch.setattr(inference_rl_check.gsm8k, "read_rows", lambda *args, **kwargs: [])
    monkeypatch.setattr(inference_rl_check.gsm8k, "tokenize_examples", lambda *args: [])
    monkeypatch.setattr(inference_rl_check.gsm8k, "length_distribution", lambda rows: distribution)
    monkeypatch.setattr(inference_rl_check.gsm8k, "select_by_token_budget", lambda *args: ([object()], 4))
    monkeypatch.setattr(inference_rl_check.gsm8k, "assert_disjoint", lambda *args: None)
    monkeypatch.setattr(inference_rl_check.gsm8k, "build_batch", lambda *args: object())
    monkeypatch.setattr(
        inference_rl_check, "training_batches", lambda *args: [object()] * inference_rl_check.TRAIN_STEPS
    )
    monkeypatch.setattr(inference_rl_check, "pack_logit_aligned", lambda batch: {})
    monkeypatch.setattr(inference_rl_check, "pack", lambda *args, **kwargs: {})
    monkeypatch.setattr(inference_rl_check, "build_payload", lambda *args, **kwargs: {"job_type": "training"})
    monkeypatch.setattr(inference_rl_check, "forward_logprobs", lambda *args: None)
    monkeypatch.setattr(inference_rl_check, "reference_answer_logprobs", lambda *args: rows)
    monkeypatch.setattr(inference_rl_check, "save_weights_only_checkpoint", lambda *args: tmp_path / "full-export")
    monkeypatch.setattr(inference_rl_check, "materialize_checkpoint_tokenizer", lambda *args: None)
    monkeypatch.setattr(inference_rl_check, "verdict", lambda *args: "synthetic-routing-only")

    def step(*args, **kwargs):
        steps.append(kwargs["learning_rate"])
        return SimpleNamespace(avg_loss=2.0)

    @contextmanager
    def gateway(path, slots, *, backend):
        assert slots == expected_slots
        assert isinstance(backend, OnPremConfig)
        events.append("gateway")
        yield object()

    @contextmanager
    def training(session, payload):
        assert payload["job_type"] == "training"
        events.append("training_start")
        try:
            yield object()
        finally:
            events.append("training_destroyed")

    def sampling(actual_ctx, session, weights_dir, token_budget, examples, validation_body):
        assert actual_ctx is ctx
        assert events == ["gateway", "training_start", "training_destroyed"]
        events.append("sampling")
        return (rows, rows)

    monkeypatch.setattr(inference_rl_check, "gateway", gateway)
    monkeypatch.setattr(inference_rl_check, "running_job", training)
    monkeypatch.setattr(inference_rl_check, "fwd_bwd_step", step)
    monkeypatch.setattr(inference_rl_check, "_onprem_sampling_and_reload", sampling)
    assert inference_rl_check._run(ctx) == "synthetic-routing-only"
    assert events == ["gateway", "training_start", "training_destroyed", "sampling"]
    assert steps == [inference_rl_check.configured_learning_rate(ctx.cfg)] * inference_rl_check.TRAIN_STEPS


